.domotics-section .thumbnail img {
  width: 100%;
  height: 100px;
  object-fit: cover;
}

/* Override inline styles for dark theme */
.domotics-section div[style*="background: white"] {
  background: rgba(15, 15, 15, 0.85) !important;
  border-color: var(--shelly-border) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
}

.domotics-section div[style*="background: #f8f9fa"] {
