// Shelly Smart Home JavaScript

// Wait for DOM to be ready
document.addEventListener('DOMContentLoaded', function() {
  // Initialize all Shelly components
  initializeShellyComponents();
});

function initializeShellyComponents() {
  // Initialize slideshow if it exists
  if (document.querySelector('.domotics-section .slideshow-container')) {
    initializeSlideshow();
  }

  // Initialize modal functionality
  if (document.querySelector('.domotics-section .modal')) {
    initializeModal();
  }

  // Initialize scroll animations
  initializeScrollAnimations();

  // Initialize smooth scrolling for any anchor links
  initializeSmoothScrolling();
}

// Slideshow functionality
function initializeSlideshow() {
  let slideIndex = 1;
  let slideInterval;

  // Make functions globally available for onclick handlers
  window.changeSlide = function(n) {
    clearInterval(slideInterval);
    showSlide(slideIndex += n);
    startAutoSlide();
  }

  window.currentSlide = function(n) {
    clearInterval(slideInterval);
    showSlide(slideIndex = n);
    startAutoSlide();
  }

  function showSlide(n) {
    const slides = document.querySelectorAll('.domotics-section .slide');
    const dots = document.querySelectorAll('.domotics-section .dot');
    const thumbnails = document.querySelectorAll('.domotics-section .thumbnail');

    if (slides.length === 0) return;

    if (n > slides.length) { slideIndex = 1 }
    if (n < 1) { slideIndex = slides.length }

    // Hide all slides
    slides.forEach(slide => {
      slide.classList.remove('active');
    });

    // Remove active class from dots and thumbnails
    dots.forEach(dot => {
      dot.classList.remove('active');
    });

    thumbnails.forEach(thumb => {
      thumb.classList.remove('active');
    });

    // Show current slide
    if (slides[slideIndex - 1]) {
      slides[slideIndex - 1].classList.add('active');
    }

    // Activate current dot
    if (dots[slideIndex - 1]) {
      dots[slideIndex - 1].classList.add('active');
    }

    // Activate current thumbnail
    if (thumbnails[slideIndex - 1]) {
      thumbnails[slideIndex - 1].classList.add('active');
    }
  }

  // Auto-advance slideshow
  function startAutoSlide() {
    slideInterval = setInterval(() => {
      changeSlide(1);
    }, 5000); // Change slide every 5 seconds
  }

  // Initialize slideshow
  showSlide(slideIndex);
  startAutoSlide();

  // Pause auto-slide on hover
  const slideshowContainer = document.querySelector('.domotics-section .slideshow-container');
  if (slideshowContainer) {
    slideshowContainer.addEventListener('mouseenter', () => {
      clearInterval(slideInterval);
    });

    slideshowContainer.addEventListener('mouseleave', () => {
      startAutoSlide();
    });
  }
}

// Modal functionality
function initializeModal() {
  const modal = document.querySelector('.domotics-section .modal');
  const modalImg = document.querySelector('.domotics-section .modal-content');
  const captionText = document.querySelector('.domotics-section .modal-caption');
  const closeBtn = document.querySelector('.domotics-section .modal .close');

  if (!modal || !modalImg) return;

  // Add click event to all gallery images
  const galleryImages = document.querySelectorAll('.domotics-section .gallery-item img');
  galleryImages.forEach(img => {
    img.style.cursor = 'pointer';
    img.addEventListener('click', function() {
      modal.style.display = 'block';
      modalImg.src = this.src;
      modalImg.alt = this.alt;
      if (captionText) {
        captionText.innerHTML = this.alt;
      }
      document.body.style.overflow = 'hidden'; // Prevent scrolling when modal is open
    });
  });

  // Close modal when clicking on X
  if (closeBtn) {
    closeBtn.addEventListener('click', closeModal);
  }

  // Close modal when clicking outside the image
  modal.addEventListener('click', function(event) {
    if (event.target === modal) {
      closeModal();
    }
  });

  // Close modal with ESC key
  document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape' && modal.style.display === 'block') {
      closeModal();
    }
  });

  function closeModal() {
    modal.style.display = 'none';
    document.body.style.overflow = ''; // Restore scrolling
  }
}

// Smooth scrolling for anchor links
function initializeSmoothScrolling() {
  // Handle any anchor links within the domotics section
  const anchorLinks = document.querySelectorAll('.domotics-section a[href^="#"]');

  anchorLinks.forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      const targetId = this.getAttribute('href');
      const targetElement = document.querySelector(targetId);

      if (targetElement) {
        e.preventDefault();

        // Calculate offset considering fixed header
        const headerHeight = document.querySelector('header') ? 
                           document.querySelector('header').offsetHeight : 0;
        const additionalOffset = 20; // Extra padding
        const targetPosition = targetElement.getBoundingClientRect().top + 
                             window.pageYOffset - headerHeight - additionalOffset;

        window.scrollTo({
          top: targetPosition,
          behavior: 'smooth'
        });
      }
    });
  });
}

// Scroll animations
function initializeScrollAnimations() {
  const animatedElements = document.querySelectorAll(
    '.domotics-section .feature-card, ' +
    '.domotics-section .room-card, ' +
    '.domotics-section .step-card, ' +
    '.domotics-section .device-item'
  );

  if (animatedElements.length === 0) return;

  // Check if IntersectionObserver is supported
  if ('IntersectionObserver' in window) {
    const observerOptions = {
      threshold: 0.05, // Trigger earlier (5% visible instead of 10%)
      rootMargin: '50px 0px' // Start animation 50px before element enters viewport
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.style.opacity = '1';
          entry.target.style.transform = 'translateY(0)';
          observer.unobserve(entry.target); // Stop observing once animated
        }
      });
    }, observerOptions);

    // Apply initial styles and observe
    animatedElements.forEach((el, index) => {
      el.style.opacity = '0';
      el.style.transform = 'translateY(20px)';
      // Faster animation (0.4s) with minimal delay between elements (0.05s)
      el.style.transition = `all 0.4s ease ${Math.min(index * 0.05, 0.3)}s`;
      observer.observe(el);
    });
  } else {
    // Fallback for browsers that don't support IntersectionObserver
    animatedElements.forEach(el => {
      el.style.opacity = '1';
      el.style.transform = 'translateY(0)';
    });
  }
}

// Utility function to handle touch/swipe on mobile for slideshow
function initializeTouchSupport() {
  const slideshowContainer = document.querySelector('.domotics-section .slideshow-container');
  if (!slideshowContainer) return;

  let touchStartX = 0;
  let touchEndX = 0;

  slideshowContainer.addEventListener('touchstart', function(e) {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });

  slideshowContainer.addEventListener('touchend', function(e) {
    touchEndX = e.changedTouches[0].screenX;
    handleSwipe();
  }, { passive: true });

  function handleSwipe() {
    const swipeThreshold = 50;
    const diff = touchStartX - touchEndX;

    if (Math.abs(diff) > swipeThreshold) {
      if (diff > 0) {
        // Swiped left, go to next slide
        if (window.changeSlide) window.changeSlide(1);
      } else {
        // Swiped right, go to previous slide
        if (window.changeSlide) window.changeSlide(-1);
      }
    }
  }
}

// Initialize touch support when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  initializeTouchSupport();
});

// Handle window resize for responsive adjustments
let resizeTimer;
window.addEventListener('resize', function() {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(function() {
    // Reinitialize components that might need adjustment
    const galleryItems = document.querySelectorAll('.domotics-section .gallery-item');
    galleryItems.forEach(item => {
      // Force aspect ratio recalculation
      item.style.height = 'auto';
    });
  }, 250);
});
